 public static boolean context(Mc mc,String boundary){if(active==null)return false;Action a=active;if(mc.player!=a.player||mc.level!=a.level||mc.gameMode==null){finish("cancelled","capability_context_changed");return false;}if(mc.paused){finish("cancelled","capability_focus_or_pause_changed");return false;}if(a.dispatched&&a.player.using&&!(a.player.main.item.equals("potion")||a.player.main.item.equals("food"))){finish("cancelled","capability_consumable_changed");return false;}return true;}
 public static boolean capabilityDispatchCheck(Mc mc,Action a){return active==a&&context(mc,"dispatch");}
 public static void finish(String status,String why){Action a=active;if(a==null)return;active=null;finishes++;terminal=status;reason=why;a.entry.status=status;a.entry.reason=why;if(a.useHeld){current.options.keyUse.setDown(false);current.gameMode.releaseUsingItem(a.player);}a.entry.result.addProperty("input_release_confirmed",true);}
 public static void failException(RuntimeException e){throw e;}
 static void ok(boolean v,String m){checks++;if(!v)throw new AssertionError(m+" phase="+phase+" terminal="+terminal+" reason="+reason+" main="+mainUses+" off="+offUses);}
 static ClassNode read(byte[] bytes){ClassNode n=new ClassNode();new ClassReader(bytes).accept(n,0);return n;}
 static Map<String,String> types(String generated){Map<String,String> m=new HashMap<>();m.put(P+"ClientActions",generated);m.put(P+"ClientActions$RuntimeAction",H+"$Action");for(String s:new String[]{"client/Minecraft=Mc","client/player/LocalPlayer=Player","world/entity/player/Player=Player","client/multiplayer/ClientLevel=Level","client/multiplayer/MultiPlayerGameMode=GameMode","client/Options=Options","client/KeyMapping=Key","world/item/ItemStack=Stack","world/level/Level=Level","client/renderer/GameRenderer=Renderer","client/renderer/ItemInHandRenderer=HandRenderer","client/Minecraft$1=Switches"}){String[] p=s.split("=");m.put("net/minecraft/"+p[0],H+"$"+p[1]);}m.put("net/neoforged/neoforge/client/ClientHooks",H+"$Hooks");m.put("net/neoforged/neoforge/client/event/InputEvent$InteractionKeyMappingTriggered",H+"$Event");m.put(P+"MovementBudget",H+"$Budget");m.put(P+"NavigationPositionGuard",H+"$Navigation");return m;}
 static void emit(ClassWriter w,MethodNode method,Map<String,String> aliases){Remapper r=new Remapper(){@Override public String map(String n){return aliases.getOrDefault(n,n);}};MethodVisitor visitor=w.visitMethod(Opcodes.ACC_PUBLIC|(method.access&Opcodes.ACC_STATIC),method.name,r.mapMethodDesc(method.desc),null,null);method.accept(new MethodRemapper(visitor,r));}
 static Class<?> nativeActions(byte[] bytes,String name)throws Exception{String target=P+name;ClassWriter w=new ClassWriter(0);w.visit(Opcodes.V21,Opcodes.ACC_PUBLIC,target,null,H,null);Set<String> keep=Set.of("preTick","postTick","useItem","finishUseItemIfObserved","useItemOwnerContext");for(MethodNode m:read(bytes).methods)if(keep.contains(m.name))emit(w,m,types(target));w.visitEnd();return MethodHandles.lookup().defineClass(w.toByteArray());}
 static Class<?> engine(byte[] bytes)throws Exception{ClassNode n=read(bytes);String target=P+"PinnedConsumeEngine";ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);w.visit(Opcodes.V21,Opcodes.ACC_PUBLIC,target,null,H+"$Mc",null);Map<String,String> aliases=types(P+"Unused");aliases.put("net/minecraft/client/Minecraft",target);MethodNode start=n.methods.stream().filter(m->m.name.equals("startUseItem")).findFirst().orElseThrow();emit(w,start,aliases);
  MethodNode keys=n.methods.stream().filter(m->m.name.equals("handleKeybinds")).findFirst().orElseThrow();MethodInsnNode call=null;for(AbstractInsnNode x:keys.instructions)if(x instanceof MethodInsnNode mi&&mi.name.equals("startUseItem"))call=mi;ok(call!=null,"engine held use call exists");AbstractInsnNode first=call;while(!(first instanceof FieldInsnNode f&&f.name.equals("rightClickDelay")))first=first.getPrevious();while(!(first instanceof MethodInsnNode m&&m.name.equals("isDown")))first=first.getPrevious();for(int k=0;k<3;k++)first=first.getPrevious();while(first.getOpcode()<0)first=first.getNext();ok(first.getOpcode()==Opcodes.ALOAD,"engine tail start");// Preserve exact branch targets via cloning.
  LabelNode end=null;for(AbstractInsnNode x=first;x!=call;x=x.getNext())if(x instanceof JumpInsnNode j){end=j.label;break;}ok(end!=null,"held use branch end");MethodNode tail=new MethodNode(Opcodes.ACC_PUBLIC,"heldUseKey","()V",null,null);Map<LabelNode,LabelNode> labels=new HashMap<>();for(AbstractInsnNode x:keys.instructions)if(x instanceof LabelNode l)labels.put(l,new LabelNode());for(AbstractInsnNode x=first;x!=end;x=x.getNext())if(!(x instanceof FrameNode)&&!(x instanceof LineNumberNode))tail.instructions.add(x.clone(labels));tail.instructions.add(labels.get(end));tail.instructions.add(new FrameNode(Opcodes.F_SAME,0,null,0,null));tail.instructions.add(new InsnNode(Opcodes.RETURN));tail.maxLocals=1;tail.maxStack=2;emit(w,tail,aliases);
  MethodVisitor init=w.visitMethod(Opcodes.ACC_PUBLIC,"<init>","()V",null,null);init.visitCode();init.visitVarInsn(Opcodes.ALOAD,0);init.visitMethodInsn(Opcodes.INVOKESPECIAL,H+"$Mc","<init>","()V",false);init.visitInsn(Opcodes.RETURN);init.visitMaxs(1,1);init.visitEnd();w.visitEnd();return MethodHandles.lookup().defineClass(w.toByteArray());}
 static Class<?> engine;static Object shield;static java.lang.reflect.Method shieldUse;
 static void installShield(byte[] bytes)throws Exception{String target=P+"PinnedShieldUse";ClassWriter w=new ClassWriter(0);w.visit(Opcodes.V21,Opcodes.ACC_PUBLIC,target,null,"java/lang/Object",null);Map<String,String> aliases=types(P+"Unused");aliases.put("net/minecraft/world/item/ShieldItem",target);for(MethodNode m:read(bytes).methods)if(m.name.equals("use"))emit(w,m,aliases);MethodVisitor init=w.visitMethod(Opcodes.ACC_PUBLIC,"<init>","()V",null,null);init.visitCode();init.visitVarInsn(Opcodes.ALOAD,0);init.visitMethodInsn(Opcodes.INVOKESPECIAL,"java/lang/Object","<init>","()V",false);init.visitInsn(Opcodes.RETURN);init.visitMaxs(1,1);init.visitEnd();w.visitEnd();Class<?> c=MethodHandles.lookup().defineClass(w.toByteArray());shield=c.getConstructor().newInstance();shieldUse=c.getMethod("use",Level.class,Player.class,InteractionHand.class);}

 static Action reset()throws Exception{current=(Mc)engine.getConstructor().newInstance();current.hitResult=net.minecraft.world.phys.BlockHitResult.miss(net.minecraft.world.phys.Vec3.ZERO,net.minecraft.core.Direction.UP,net.minecraft.core.BlockPos.ZERO);active=new Action(current);finishes=mainUses=offUses=keyUps=releases=0;terminal=reason="";observationHook=clickHook=releaseHook=useHook=null;return active;}
 static void invoke(Class<?> c,String method)throws Exception{phase=method;try{c.getMethod(method).invoke(null);}catch(InvocationTargetException e){throw new AssertionError(method,e.getCause());}}
 static void key()throws Exception{phase="vanilla_keybinds";try{engine.getMethod("heldUseKey").invoke(current);}catch(InvocationTargetException e){throw new AssertionError("engine",e.getCause());}}
 static void tick(Class<?> c,Runnable beforePre,Runnable entities)throws Exception{if(beforePre!=null){phase="server_tasks_before_pre";beforePre.run();}invoke(c,"preTick");key();if(entities!=null){phase="entities_after_keybinds";entities.run();}invoke(c,"postTick");}
 static void dispatch(Class<?> c)throws Exception{tick(c,null,null);ok(mainUses==1&&offUses==0&&active!=null&&current.options.keyUse.down,"single Post dispatch");}
 static void record(String name){JsonObject row=new JsonObject();row.addProperty("case",name);row.addProperty("status",terminal);row.addProperty("reason",reason);row.addProperty("main_use_calls",mainUses);row.addProperty("offhand_use_calls",offUses);row.addProperty("key_up_calls",keyUps);row.addProperty("release_calls",releases);cases.add(row);}
