  for(String after:List.of("bottle","food","potion")){a=reset();if(after.equals("food"))current.player.main=new Stack("food",1);dispatch(fixed);for(int i=0;i<31;i++){tick(fixed,null,null);ok(active==a&&current.player.using&&current.options.keyUse.down&&mainUses==1&&offUses==0,"32-tick pending hold stays owned");}tick(fixed,()->{current.player.main=new Stack(after,1);current.player.using=false;},null);ok(active==null&&terminal.equals("succeeded")&&reason.equals("item_use_finished_observed"),"Pre completes same-count stopped use");ok(mainUses==1&&offUses==0&&keyUps==1&&releases==1,"no extra main/offhand use");record("fixed_pre_stop_"+after+"_shield");}
  reset();dispatch(fixed);tick(fixed,null,()->{current.player.main=new Stack("bottle",1);current.player.using=false;});ok(terminal.equals("succeeded")&&mainUses==1&&offUses==0,"entity-phase completion handled in same Post");record("fixed_entity_post_completion");
  reset();dispatch(fixed);tick(fixed,()->current.player.main=new Stack("bottle",1),null);ok(reason.equals("capability_consumable_changed")&&mainUses==1&&offUses==0,"partial bottle sync still guarded before completion");record("partial_sync_guard_preserved");
  reset();dispatch(fixed);tick(fixed,()->current.player.main.count=0,null);ok(terminal.equals("succeeded")&&mainUses==1&&offUses==0,"exact count-change predicate");record("count_decrement_pre_completion");
  a=reset();a.dispatched=true;a.useHeld=true;a.useBeforeCount=1;a.dispatchTick=a.entry.ticks=2;current.options.keyUse.down=true;invoke(fixed,"postTick");ok(active==a&&finishes==0,"same dispatch tick cannot use stopped predicate");record("same_tick_not_early");
  a=reset();invoke(fixed,"preTick");ok(active==a&&!a.dispatched&&mainUses==0&&offUses==0&&!current.options.keyUse.down,"Pre never dispatches");record("undispatched_pre_noop");
  a=reset();dispatch(fixed);Action owner=a;Action replacement=new Action(current);current.player.using=false;observationHook=()->active=replacement;invoke(fixed,"preTick");ok(active==replacement&&finishes==0&&keyUps==0,"observation callback replacement owner untouched");record("replacement_during_observation");
  a=reset();dispatch(fixed);current.player.using=false;observationHook=()->current.level=new Level();invoke(fixed,"preTick");ok(active==a&&finishes==0&&keyUps==0,"changed context during observation not completed");record("context_during_observation");
  reset();dispatch(fixed);tick(fixed,()->current.level=new Level(),null);ok(reason.equals("capability_context_changed")&&mainUses==1&&offUses==0,"changed context entry cancels before keybinds");record("changed_context_entry");
  reset();dispatch(fixed);finish("cancelled","cancel_requested");tick(fixed,null,null);ok(mainUses==1&&offUses==0&&finishes==1,"cancelled owner never restarts");record("interrupted_action");
  a=reset();dispatch(fixed);for(int i=0;i<40;i++)tick(fixed,null,null);ok(reason.equals("item_use_budget_exhausted")&&mainUses==1&&offUses==0,"pending use retains original Post budget");record("unchanged_budget");
  reset();clickHook=()->finish("cancelled","callback_cancel");tick(fixed,null,null);ok(mainUses==0&&offUses==0&&!current.options.keyUse.down&&finishes==1,"cancel during click callback stops dispatch");record("cancel_during_click");
  reset();useHook=()->finish("cancelled","callback_cancel");tick(fixed,null,null);ok(mainUses==1&&offUses==0&&!current.options.keyUse.down&&finishes==1,"cancel during dispatched use returns without replay");record("cancel_during_use");
  a=reset();dispatch(fixed);current.player.using=false;Action replacement2=new Action(current);observationHook=()->active=replacement2;invoke(fixed,"postTick");ok(active==replacement2&&finishes==0&&keyUps==0,"Post observation also preserves replacement owner");record("post_replacement_during_observation");
  a=reset();dispatch(fixed);current.player.using=false;observationHook=()->current.player=new Player();invoke(fixed,"preTick");ok(active==a&&finishes==0&&keyUps==0,"changed player during completion observation not completed");record("player_during_observation");
  a=reset();dispatch(fixed);current.player.using=false;observationHook=()->current.gameMode=null;invoke(fixed,"preTick");ok(active==a&&finishes==0&&keyUps==0,"missing game mode during completion observation not completed");record("mode_during_observation");
  a=reset();dispatch(old);tick(old,null,()->{current.player.main=new Stack("bottle",1);current.player.using=false;});JsonObject oldWire=a.entry.json(false);a=reset();dispatch(fixed);tick(fixed,()->{current.player.main=new Stack("bottle",1);current.player.using=false;},null);JsonObject fixedWire=a.entry.json(false);oldWire.remove("action_id");fixedWire.remove("action_id");ok(oldWire.equals(fixedWire),"actual Entry JSON schema/values unchanged for equivalent Post/Pre completion");record("public_result_schema_equivalence");
